/**
 * Easing Functions
 *
 * A collection of easing functions for smooth animations and transitions.
 * Based on Robert Penner's easing equations.
 *
 * @module @three-blocks/pro/utils/easeFunction
 * @private
 * @short Common easing functions for animation curves.
 * @category Utils
 * @tags Animation, Easing, Interpolation
 */
/**
 * Ease out back - overshoots then settles.
 * Creates a slight overshoot effect at the end of the animation.
 *
 * @param {number} x - Progress value between 0 and 1
 * @returns {number} Eased value between 0 and ~1.05 (overshoots slightly)
 * @example
 * const progress = easeOutBack(0.5); // ~0.877
 */
export function easeOutBack(x: number): number;
/**
 * Ease in back - pulls back then accelerates forward.
 * Creates a slight anticipation effect at the start of the animation.
 *
 * @param {number} x - Progress value between 0 and 1
 * @returns {number} Eased value between ~-0.05 and 1 (undershoots slightly at start)
 * @example
 * const progress = easeInBack(0.5); // ~0.123
 */
export function easeInBack(x: number): number;
/**
 * Ease out cubic - decelerating cubic curve.
 * Starts fast and slows down towards the end.
 *
 * @param {number} x - Progress value between 0 and 1
 * @returns {number} Eased value between 0 and 1
 * @example
 * const progress = easeOutCubic(0.5); // 0.875
 */
export function easeOutCubic(x: number): number;
/**
 * Ease in-out cubic - accelerates then decelerates.
 * Smooth S-curve transition using cubic interpolation.
 *
 * @param {number} x - Progress value between 0 and 1
 * @returns {number} Eased value between 0 and 1
 * @example
 * const progress = easeInOutCubic(0.5); // 0.5
 */
export function easeInOutCubic(x: number): number;
/**
 * Ease in-out quadratic - accelerates then decelerates.
 * Smooth S-curve transition using quadratic interpolation.
 * Gentler than cubic easing.
 *
 * @param {number} x - Progress value between 0 and 1
 * @returns {number} Eased value between 0 and 1
 * @example
 * const progress = easeInOutQuad(0.5); // 0.5
 */
export function easeInOutQuad(x: number): number;
/**
 * Ease in exponential - slow start with exponential acceleration.
 * Starts very slowly and accelerates rapidly towards the end.
 *
 * @param {number} x - Progress value between 0 and 1
 * @returns {number} Eased value between 0 and 1
 * @example
 * const progress = easeInExpo(0.5); // ~0.031
 */
export function easeInExpo(x: number): number;
